+import {Options, RuleType} from '../rules';
+import RuleBuilder, {BooleanOptionBuilder, DropdownOptionBuilder, ExampleBuilder, NumberOptionBuilder, OptionBuilderBase, TextAreaOptionBuilder, TextOptionBuilder} from './rule-builder';
+import dedent from 'ts-dedent';
+
+type ListStyle = 'bullet' | 'number';
+type OrderedListStyle = 'always-one' | 'increment';
+
+class AutoTocOptions implements Options {
+  listStyle: ListStyle = 'bullet';
+  bulletMarker: string = '-';
+  orderedListStyle: OrderedListStyle = 'always-one';
+  indentSize: Number = 2;
+  minLevel: Number = 2;
+  maxLevel: Number = 6;
+  title: string = '';
+  useExplicitIds: boolean = false;
+  stripFormattingInToc: boolean = false;
+  excludeHeadings: string[] = [];
+}
+
+type Heading = {
+  level: number,
+  text: string,
+};
+
+const tocStartMarker = /^\\s*<!--\\s*toc\\s*-->\\s*$/i;
+const tocEndMarker = /^\\s*<!--\\s*\\/toc\\s*-->\\s*$/i;
+const atxHeading = /^(?: {0,3})(#{1,6})(?:[ \	]+(.*)|[ \	]*)$/;
+
+@RuleBuilder.register
+export default class AutoToc extends RuleBuilder<AutoTocOptions> {
+  constructor() {
+    super({
+      nameKey: 'rules.auto-toc.name',
+      descriptionKey: 'rules.auto-toc.description',
+      type: RuleType.CONTENT,
+    });
+  }
+
+  get OptionsClass(): new () => AutoTocOptions {
+    return AutoTocOptions;
+  }
+
+  apply(text: string, options: AutoTocOptions): string {
+    const lines = text.split(/\\r?\
/);
+    const startIndex = lines.findIndex((line) => tocStartMarker.test(line));
+    if (startIndex === -1) {
+      return text;
+    }
+
+    const endIndex = lines.findIndex((line, index) => index > startIndex && tocEndMarker.test(line));
+    const headings = this.getHeadings(lines, startIndex, endIndex, options);
+    const tocLines = this.buildToc(lines[startIndex], endIndex === -1 ? '<!-- /toc -->' : lines[endIndex], headings, options);
+
+    const suffixStart = endIndex === -1 ? startIndex + 1 : endIndex + 1;
+    const suffix = lines.slice(suffixStart);
+    while (suffix.length > 0 && suffix[0].trim() === '') {
+      suffix.shift();
+    }
+
+    return [...lines.slice(0, startIndex), ...tocLines, ...suffix].join('\
');
+  }
+
+  private getHeadings(lines: string[], tocStart: number, tocEnd: number, options: AutoTocOptions): Heading[] {
+    const headings: Heading[] = [];
+    let inYaml = false;
+    let inFence: string = null;
+    let inMath = false;
+
+    for (let index = 0; index < lines.length; index++) {
+      const line = lines[index];
+      if (index === 0 && /^---\\s*$/.test(line)) {
+        inYaml = true;
+        continue;
+      }
+      if (inYaml) {
+        if (/^(---|\\.\\.\\.)\\s*$/.test(line)) {
+          inYaml = false;
+        }
+        continue;
+      }
+
+      const fence = line.match(/^\\s*(`{3,}|~{3,})/);
+      if (fence) {
+        if (inFence === null) {
+          inFence = fence[1][0];
+        } else if (fence[1][0] === inFence) {
+          inFence = null;
+        }
+        continue;
+      }
+      if (inFence !== null || /^(?:\	| {4})/.test(line)) {
+        continue;
+      }
+
+      if (/^\\s*\\$\\$\\s*$/.test(line) || /^\\s*\\\\\\[\\s*$/.test(line)) {
+        inMath = !inMath;
+        continue;
+      }
+      if (inMath) {
+        continue;
+      }
+      if (index > tocStart && (tocEnd === -1 || index < tocEnd)) {
+        continue;
+      }
+
+      const match = line.match(atxHeading);
+      if (match === null) {
+        continue;
+      }
+      const level = match[1].length;
+      if (level < Number(options.minLevel) || level > Number(options.maxLevel)) {
+        continue;
+      }
+
+      const headingText = match[2] ?? '';
+      if (!this.isExcluded(headingText, options.excludeHeadings)) {
+        headings.push({level, text: headingText});
+      }
+    }
+
+    return headings;
+  }
+
+  private buildToc(startMarker: string, endMarker: string, headings: Heading[], options: AutoTocOptions): string[] {
+    const anchors = new Map<string, number>();
+    const items = headings.map((heading, index) => {
+      const {displayText, anchor} = this.headingParts(heading.text, options);
+      const used = anchors.get(anchor) ?? 0;
+      anchors.set(anchor, used + 1);
+      const uniqueAnchor = used === 0 ? anchor : `${anchor}-${used}`;
+      const indentation = ' '.repeat((heading.level - Number(options.minLevel)) * Number(options.indentSize));
+      const marker = options.listStyle === 'number' ? `${options.orderedListStyle === 'increment' ? index + 1 : 1}.` : options.bulletMarker;
+      return `${indentation}${marker} [${displayText}](#${uniqueAnchor})`;
+    });
+
+    const result = [startMarker, ''];
+    if (options.title !== '') {
+      result.push(options.title, '');
+    }
+    result.push(...items, '', endMarker, '');
+    return result;
+  }
+
+  private headingParts(heading: string, options: AutoTocOptions): {displayText: string, anchor: string} {
+    const withoutClosingHashes = heading.replace(/[ \	]+#+[ \	]*$/, '');
+    const explicitId = withoutClosingHashes.match(/\\s*\\{#([^}]+)\\}\\s*$/);
+    const text = options.useExplicitIds && explicitId !== null ? withoutClosingHashes.slice(0, explicitId.index).trimEnd() : withoutClosingHashes;
+    const linkText = this.resolveLinksAndImages(text);
+    const displayText = options.stripFormattingInToc ? this.stripFormatting(linkText) : linkText;
+    const baseAnchor = options.useExplicitIds && explicitId !== null ? explicitId[1] : this.stripFormatting(linkText);
+    return {displayText, anchor: this.toAnchor(baseAnchor)};
+  }
+
+  private resolveLinksAndImages(text: string): string {
+    return text
+        .replace(/!\\[\\[[^\\]]*\\]\\]/g, '')
+        .replace(/!\\[[^\\]]*\\]\\([^)]*\\)/g, '')
+        .replace(/\\[\\[([^\\]]+)\\]\\]/g, (_, value: string) => value.split('|').pop())
+        .replace(/\\[([^\\]]*)\\]\\([^)]*\\)/g, '$1');
+  }
+
+  private stripFormatting(text: string): string {
+    return text
+        .replace(/<[^>]*>/g, '')
+        .replace(/(\\*\\*|__|~~)(.*?)\\1/g, '$2')
+        .replace(/([*`])/g, '')
+        .replace(/\\\\(.)/g, '$1');
+  }
+
+  private toAnchor(text: string): string {
+    return text.toLowerCase()
+        .replace(/\\s+/g, '-')
+        .replace(/[^a-z0-9_-]/g, '')
+        .replace(/-+/g, '-')
+        .replace(/^-+|-+$/g, '');
+  }
+
+  private isExcluded(heading: string, exclusions: string[]): boolean {
+    return exclusions.some((exclusion) => {
+      if (exclusion.length > 2 && exclusion.startsWith('/') && exclusion.endsWith('/')) {
+        try {
+          return new RegExp(exclusion.slice(1, -1), 'i').test(heading);
+        } catch (_) {
+          return false;
+        }
+      }
+      return exclusion.toLocaleLowerCase() === heading.toLocaleLowerCase();
+    });
+  }
+
+  get exampleBuilders(): ExampleBuilder<AutoTocOptions>[] {
+    return [
+      new ExampleBuilder({
+        description: 'Generates a table of contents for ATX headings after an opt-in marker.',
+        before: dedent`
+          # Title
+
+          <!-- toc -->
+
+          <!-- /toc -->
+
+          ## First section
+          ### Nested section
+        `,
+        after: dedent`
+          # Title
+
+          <!-- toc -->
+
+          - [First section](#first-section)
+            - [Nested section](#nested-section)
+
+          <!-- /toc -->
+
+          ## First section
+          ### Nested section
+        `,
+      }),
+    ];
+  }
+
+  get optionBuilders(): OptionBuilderBase<AutoTocOptions>[] {
+    return [
+      new DropdownOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.list-style.name', descriptionKey: 'rules.auto-toc.list-style.description', optionsKey: 'listStyle', records: [{value: 'bullet', description: 'Use bullet list items'}, {value: 'number', description: 'Use numbered list items'}]}),
+      new TextOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.bullet-marker.name', descriptionKey: 'rules.auto-toc.bullet-marker.description', optionsKey: 'bulletMarker'}),
+      new DropdownOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.ordered-list-style.name', descriptionKey: 'rules.auto-toc.ordered-list-style.description', optionsKey: 'orderedListStyle', records: [{value: 'always-one', description: 'Use 1. for every item'}, {value: 'increment', description: 'Increment every item'}]}),
+      new NumberOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.indent-size.name', descriptionKey: 'rules.auto-toc.indent-size.description', optionsKey: 'indentSize'}),
+      new NumberOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.min-level.name', descriptionKey: 'rules.auto-toc.min-level.description', optionsKey: 'minLevel'}),
+      new NumberOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.max-level.name', descriptionKey: 'rules.auto-toc.max-level.description', optionsKey: 'maxLevel'}),
+      new TextOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.title.name', descriptionKey: 'rules.auto-toc.title.description', optionsKey: 'title'}),
+      new BooleanOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.use-explicit-ids.name', descriptionKey: 'rules.auto-toc.use-explicit-ids.description', optionsKey: 'useExplicitIds'}),
+      new BooleanOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.strip-formatting-in-toc.name', descriptionKey: 'rules.auto-toc.strip-formatting-in-toc.description', optionsKey: 'stripFormattingInToc'}),
+      new TextAreaOptionBuilder({OptionsClass: AutoTocOptions, nameKey: 'rules.auto-toc.exclude-headings.name', descriptionKey: 'rules.auto-toc.exclude-headings.description', optionsKey: 'excludeHeadings'}),
+    ];
+  }
+}
